import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"45、【萃】 坤下兌上","description":"橫渠易說 - 45、【萃】 坤下兌上","frontmatter":{"title":"45、【萃】 坤下兌上","description":"橫渠易說 - 45、【萃】 坤下兌上"},"headers":[],"relativePath":"classics/hengqu/047.md","filePath":"classics/hengqu/047.md"}'),l={name:"classics/hengqu/047.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_45、【萃】-坤下兌上" tabindex="-1">45、【萃】 坤下兌上 <a class="header-anchor" href="#_45、【萃】-坤下兌上" aria-label="Permalink to “45、【萃】 坤下兌上”">​</a></h1><p>姤者遇也，物相遇而後聚，故受之以萃。 與渙卦義同，故繇辭互見。 萃而不見大人之德，吝道也。</p><h3 id="彖曰-萃-聚也-順以說-剛中而應-故聚也。-王假有廟-致孝享也。-利見大人亨-聚以正也。-用大牲吉-利有攸往-順天命也。觀其所聚而天地萬物之情可見矣。" tabindex="-1">彖曰：萃，聚也，順以說，剛中而應，故聚也。“王假有廟”，致孝享也。“利見大人亨”，聚以正也。“用大牲吉，利有攸往”，順天命也。觀其所聚而天地萬物之情可見矣。 <a class="header-anchor" href="#彖曰-萃-聚也-順以說-剛中而應-故聚也。-王假有廟-致孝享也。-利見大人亨-聚以正也。-用大牲吉-利有攸往-順天命也。觀其所聚而天地萬物之情可見矣。" aria-label="Permalink to “彖曰：萃，聚也，順以說，剛中而應，故聚也。“王假有廟”，致孝享也。“利見大人亨”，聚以正也。“用大牲吉，利有攸往”，順天命也。觀其所聚而天地萬物之情可見矣。”">​</a></h3><h3 id="象曰-澤上於地-萃-君子以除戎器-戒不虞。" tabindex="-1">象曰：澤上於地，萃，君子以除戎器，戒不虞。 <a class="header-anchor" href="#象曰-澤上於地-萃-君子以除戎器-戒不虞。" aria-label="Permalink to “象曰：澤上於地，萃，君子以除戎器，戒不虞。”">​</a></h3><p>聚而致享，必有廟乃盡其實。 聚而不見大人之德，吝道也。 聚不以正，私邪勝也。 富聚之世，順天之命，用大牲有所進為宜。 散而通之，順天命而不凝於物也。凝一作疑。</p><h3 id="初六-有孚不終-乃亂乃萃。若號一握-為笑勿恤-往無咎。-象曰-乃亂乃萃-其志亂也。" tabindex="-1">初六，有孚不終，乃亂乃萃。若號一握，為笑勿恤，往無咎。 象曰：“乃亂乃萃”，其志亂也。 <a class="header-anchor" href="#初六-有孚不終-乃亂乃萃。若號一握-為笑勿恤-往無咎。-象曰-乃亂乃萃-其志亂也。" aria-label="Permalink to “初六，有孚不終，乃亂乃萃。若號一握，為笑勿恤，往無咎。 象曰：“乃亂乃萃”，其志亂也。”">​</a></h3><p>萃聚之世，物各以近相求，所處遠者，雖有其應，不能專一。初六履不以中，萃而志亂，故為眾輕侮，若能啼號齊諮，專一其守，不恤眾侮，則往而無咎。</p><h3 id="六二-引吉-無咎。孚乃利用禴。-象曰-引吉無咎-中未變也。" tabindex="-1">六二，引吉，無咎。孚乃利用禴。 象曰：“引吉無咎”，中未變也。 <a class="header-anchor" href="#六二-引吉-無咎。孚乃利用禴。-象曰-引吉無咎-中未變也。" aria-label="Permalink to “六二，引吉，無咎。孚乃利用禴。 象曰：“引吉無咎”，中未變也。”">​</a></h3><p>物思其聚之時，能自持不變，引而後往，吉乃無咎。凡言“利用禴”，皆誠素著白於幽明之際，未孚而略禮，則神怒而民怨。</p><h3 id="六三-萃如嗟如-無攸利。往無咎-小吝。-象曰-往無咎-上巽也。" tabindex="-1">六三，萃如嗟如，無攸利。往無咎，小吝。 象曰：“往無咎”，上巽也。 <a class="header-anchor" href="#六三-萃如嗟如-無攸利。往無咎-小吝。-象曰-往無咎-上巽也。" aria-label="Permalink to “六三，萃如嗟如，無攸利。往無咎，小吝。 象曰：“往無咎”，上巽也。”">​</a></h3><h3 id="九四-大吉-無咎-象曰-大吉無咎-位不當也。" tabindex="-1">九四，大吉，無咎， 象曰：“大吉無咎”，位不當也。 <a class="header-anchor" href="#九四-大吉-無咎-象曰-大吉無咎-位不當也。" aria-label="Permalink to “九四，大吉，無咎， 象曰：“大吉無咎”，位不當也。”">​</a></h3><p>位非極顯而有物之萃，非大吉則悔吝必矣。</p><h3 id="九五-萃有位-無咎。匪孚-元永貞-悔亡。-象曰-萃有位-志未光也。" tabindex="-1">九五，萃有位，無咎。匪孚，元永貞，悔亡。 象曰：“萃有位”，志未光也。 <a class="header-anchor" href="#九五-萃有位-無咎。匪孚-元永貞-悔亡。-象曰-萃有位-志未光也。" aria-label="Permalink to “九五，萃有位，無咎。匪孚，元永貞，悔亡。 象曰：“萃有位”，志未光也。”">​</a></h3><p>居得盛位不能見，以大人之德系應於二，故曰“有位”，履非不正，故無咎。然非君人之大信，為德非厚，不能無悔，故元永貞而後悔亡。</p><h3 id="上六-齊諮涕洟-無咎。-象曰-齊諮涕洟-未安上也。" tabindex="-1">上六，齊諮涕洟，無咎。 象曰：“齊諮涕洟”，未安上也。 <a class="header-anchor" href="#上六-齊諮涕洟-無咎。-象曰-齊諮涕洟-未安上也。" aria-label="Permalink to “上六，齊諮涕洟，無咎。 象曰：“齊諮涕洟”，未安上也。”">​</a></h3><p>以陰居上，極物之萃，非所堪也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
